// sidepulse:managed-pi-extension
//
// SidePulse status for pi (https://sidepulse.io).
//
// Generated by `sidepulse setup` (or `sidepulse agent-monitor install pi`), which
// overwrites this file; remove it with `sidepulse agent-monitor uninstall pi`.
// Set PI_SIDEPULSE=0 to turn it off for one pi process.
//
// pi has no hook configuration, so this extension forwards pi's lifecycle events to
// SidePulse's hook entry point as JSON on stdin. SidePulse (sidepulse/pi_hook.py) maps
// them onto agent states: working, tool running, waiting for input, done, or failed.
//
// The extension deliberately imports nothing from pi, so it loads on any pi version.
import { spawn } from "node:child_process";
import { homedir } from "node:os";

const HOOK_COMMAND: string[] = __SIDEPULSE_HOOK_COMMAND__;

const HOOK_TIMEOUT_MS = 5_000;
const SHUTDOWN_FLUSH_MS = 2_000;
const MAX_STRING = 400;
// Superseded by any newer event while still queued, so a burst of fast tool calls
// cannot build a backlog of hook processes.
const TRANSIENT_EVENTS = new Set(["tool_execution_start", "tool_execution_end"]);

type Payload = Record<string, unknown>;
type Job = { payload: Payload; transient: boolean };
type Context = {
	cwd: string;
	mode?: string;
	model?: { id?: string };
	sessionManager: { getSessionId(): string; getSessionFile(): string | undefined };
	isIdle(): boolean;
};
type Pi = { on(event: string, handler: (event: any, ctx: Context) => unknown): unknown };

function disabled(): boolean {
	const flag = (process.env.PI_SIDEPULSE ?? "").trim().toLowerCase();
	return ["0", "false", "off", "no"].includes(flag);
}

function truncate(value: unknown, max = MAX_STRING): string | undefined {
	if (typeof value !== "string") return undefined;
	return value.length > max ? `${value.slice(0, max)}…` : value;
}

/** Keep tool arguments small: SidePulse only needs enough to label the call. */
function summarizeArgs(args: unknown): Payload | undefined {
	if (args === null || typeof args !== "object" || Array.isArray(args)) return undefined;
	const out: Payload = {};
	for (const [key, value] of Object.entries(args as Payload)) {
		if (typeof value === "string") out[key] = truncate(value);
		else if (typeof value === "number" || typeof value === "boolean") out[key] = value;
	}
	return out;
}

function textOf(content: unknown): string {
	if (typeof content === "string") return content;
	if (!Array.isArray(content)) return "";
	return content
		.filter((part) => part?.type === "text" && typeof part.text === "string")
		.map((part) => part.text as string)
		.join("\n");
}

export default function sidepulse(pi: Pi) {
	if (disabled() || HOOK_COMMAND.length === 0) return;

	// Hooks run one at a time so SidePulse sees events in order.
	let queue: Job[] = [];
	let running: Promise<void> | null = null;
	// The final assistant message of the current run, reported once the run settles.
	let lastAssistant: Payload | null = null;

	function runHook(payload: Payload): Promise<void> {
		return new Promise((resolve) => {
			let finished = false;
			let timer: ReturnType<typeof setTimeout> | undefined;
			const done = () => {
				if (finished) return;
				finished = true;
				clearTimeout(timer);
				resolve();
			};
			let child: ReturnType<typeof spawn>;
			try {
				child = spawn(HOOK_COMMAND[0], HOOK_COMMAND.slice(1), {
					cwd: homedir(),
					// Own process group, so Ctrl+C in pi's terminal cannot kill a hook mid-write.
					detached: true,
					stdio: ["pipe", "ignore", "ignore"],
				});
			} catch {
				done();
				return;
			}
			timer = setTimeout(() => {
				try {
					child.kill();
				} catch {}
				done();
			}, HOOK_TIMEOUT_MS);
			child.on("error", done);
			child.on("close", done);
			child.stdin?.on("error", () => {});
			child.stdin?.end(JSON.stringify(payload));
		});
	}

	function pump(): Promise<void> {
		if (running) return running;
		running = (async () => {
			while (queue.length > 0) await runHook(queue.shift()!.payload);
		})().finally(() => {
			running = null;
		});
		return running;
	}

	function send(piEvent: string, ctx: Context, fields: Payload = {}): void {
		let payload: Payload;
		try {
			payload = {
				pi_event: piEvent,
				session_id: ctx.sessionManager.getSessionId(),
				session_file: ctx.sessionManager.getSessionFile(),
				cwd: ctx.cwd,
				pi_mode: ctx.mode,
				model: ctx.model?.id,
				idle: ctx.isIdle(),
				...fields,
			};
		} catch {
			return; // Stale context after the session was replaced.
		}
		queue = queue.filter((job) => !job.transient);
		queue.push({ payload, transient: TRANSIENT_EVENTS.has(piEvent) });
		void pump();
	}

	async function flush(timeoutMs: number): Promise<void> {
		let timer: ReturnType<typeof setTimeout> | undefined;
		await Promise.race([pump(), new Promise<void>((resolve) => (timer = setTimeout(resolve, timeoutMs)))]);
		clearTimeout(timer);
	}

	pi.on("session_start", (event, ctx) => {
		lastAssistant = null;
		send("session_start", ctx, { reason: event.reason });
	});

	pi.on("before_agent_start", (event, ctx) => {
		lastAssistant = null;
		send("before_agent_start", ctx, {
			message_type: event.messageType,
			prompt: event.messageType === "user" ? truncate(event.prompt, 2_000) : undefined,
		});
	});

	pi.on("tool_execution_start", (event, ctx) => {
		send("tool_execution_start", ctx, {
			tool_name: event.toolName,
			tool_call_id: event.toolCallId,
			args: summarizeArgs(event.args),
		});
	});

	pi.on("tool_execution_end", (event, ctx) => {
		send("tool_execution_end", ctx, {
			tool_name: event.toolName,
			tool_call_id: event.toolCallId,
			is_error: event.isError === true,
			duration_ms: event.durationMs,
			error_text: event.isError ? truncate(textOf(event.result?.content).trim()) : undefined,
		});
	});

	pi.on("ui_prompt_start", (event, ctx) => {
		send("ui_prompt_start", ctx, { kind: event.kind, title: truncate(event.title) });
	});

	pi.on("ui_prompt_end", (event, ctx) => {
		send("ui_prompt_end", ctx, { kind: event.kind });
	});

	pi.on("session_before_compact", (event, ctx) => {
		send("session_before_compact", ctx, { reason: event.reason, will_retry: event.willRetry });
	});

	pi.on("session_compact", (event, ctx) => {
		send("session_compact", ctx, { reason: event.reason, will_retry: event.willRetry });
	});

	pi.on("session_compact_failed", (event, ctx) => {
		send("session_compact_failed", ctx, {
			reason: event.reason,
			aborted: event.aborted === true,
			error_message: truncate(event.errorMessage),
		});
	});

	// agent_end is not final: pi may still retry, compact, or run queued messages.
	// Remember the reply here and report it from agent_settled.
	pi.on("agent_end", (event) => {
		const messages: any[] = Array.isArray(event.messages) ? event.messages : [];
		for (let i = messages.length - 1; i >= 0; i--) {
			const message = messages[i];
			if (message?.role !== "assistant") continue;
			lastAssistant = {
				assistant_text: textOf(message.content).slice(-4_000),
				stop_reason: message.stopReason,
				error_message: truncate(message.errorMessage),
			};
			return;
		}
	});

	pi.on("agent_settled", (event, ctx) => {
		const last = lastAssistant ?? {};
		lastAssistant = null;
		send("agent_settled", ctx, { aborted: event.aborted === true, ...last });
	});

	pi.on("session_shutdown", async (event, ctx) => {
		send("session_shutdown", ctx, { reason: event.reason });
		// On quit the process is about to exit, so deliver what is still queued.
		if (event.reason === "quit") await flush(SHUTDOWN_FLUSH_MS);
	});
}
